export namespace IDiscussionBoardPasswordReset {
  /**
   * Request to reset a contributor's password using a valid reset token.
   *
   * This DTO represents the second step of the password reset workflow. It
   * accepts a reset token that was previously generated by the
   * request-password-reset endpoint and the new password that will replace
   * the old one.
   *
   * The reset token must be valid (not expired, not previously used) and must
   * have been generated within 30 minutes. The new password must meet strict
   * security requirements: minimum 8 characters, at least one uppercase
   * letter, one lowercase letter, one numeric digit, and one special
   * character. Passwords cannot match the contributor's previous password to
   * prevent credential reuse.
   *
   * Upon successful submission, the new password is hashed using bcrypt with
   * minimum 12 salt rounds and replaces the old password. The
   * password_changed_at timestamp is updated, and all existing sessions for
   * the contributor are invalidated, requiring re-authentication on all
   * devices.
   */
  export type ICreate = {
    /**
     * Valid reset token generated by the request-password-reset endpoint.
     * Must not be expired (valid for 30 minutes from generation) or
     * previously used. Token validity is cryptographically verified before
     * processing. If token is invalid, expired, or already consumed, the
     * operation is rejected with security-conscious error messaging that
     * does not reveal specific failure reason.
     */
    reset_token: string;

    /**
     * New password for the contributor account. Must be at least 8
     * characters in length and include at least one uppercase letter, one
     * lowercase letter, one numeric digit, and one special character.
     * Password strength validation occurs before hashing. Cannot match the
     * contributor's previous password to prevent reuse of recently
     * compromised credentials.
     */
    new_password: string;
  };
}
